{"path": "durations.py", "content": "import re

_PART = re.compile(r'([0-9]+)([hms])')
_SPACES = re.compile(r' *')
_UNITS = {'h': 3600, 'm': 60, 's': 1}
_ORDER = 'hms'


def parse_duration(text):
    """See SPEC.md."""
    if not isinstance(text, str) or not text:
        raise ValueError(f'invalid duration: {text!r}')
    total = 0
    last = -1
    pos = 0
    while pos < len(text):
        if pos > 0:
            # Spaces are allowed only between parts.
            pos = _SPACES.match(text, pos).end()
            if pos == len(text):
                raise ValueError(f'invalid duration: {text!r}')
        m = _PART.match(text, pos)
        if not m:
            raise ValueError(f'invalid duration: {text!r}')
        index = _ORDER.index(m.group(2))
        if index <= last:
            raise ValueError(f'repeated or out-of-order unit in {text!r}')
        last = index
        total += int(m.group(1)) * _UNITS[m.group(2)]
        pos = m.end()
    return total
"}

